<script lang="ts">
  import {untrack} from 'svelte'; import {calculateGradebook,requiredAverageForTarget} from '$lib/domain/grades/calculator'; import type {GradebookDocument,GradeCategory} from '$lib/domain/grades/types'; let {initial,onChange=()=>{}}:{initial:GradebookDocument;onChange?:(gradebook:GradebookDocument)=>void}=$props(); let name=$state(untrack(()=>initial.name)); let categories=$state<GradeCategory[]>(untrack(()=>structuredClone(initial.categories))); let gradingScale=$state(untrack(()=>structuredClone(initial.gradingScale))); let target=$state(80); let whatIfAssessmentId=$state(''); let whatIfEarned=$state<number|null>(null); let whatIfPossible=$state<number|null>(null); const result=$derived(calculateGradebook(categories)); const remainingWeight=$derived(Math.max(0,100-result.gradedWeight)); const required=$derived(requiredAverageForTarget(target,result.earnedWeightedPoints,remainingWeight)); const pendingAssessments=$derived(categories.flatMap(category=>category.assessments.filter(a=>a.earned===null||a.possible===null).map(a=>({categoryId:category.id,assessmentId:a.id,label:`${category.name} · ${a.name}`})))); const simulatedCategories=$derived.by(()=>{if(!whatIfAssessmentId||whatIfEarned===null||whatIfPossible===null||whatIfPossible<=0)return null;const clone=structuredClone(categories);for(const category of clone){const assessment=category.assessments.find(i=>i.id===whatIfAssessmentId);if(assessment){assessment.earned=whatIfEarned;assessment.possible=whatIfPossible;break;}}return clone;}); const projectedResult=$derived(simulatedCategories?calculateGradebook(simulatedCategories):null);
  $effect(()=>onChange({version:1,id:initial.id,name,categories:structuredClone(categories),gradingScale:structuredClone(gradingScale),updatedAt:new Date().toISOString()}));
  function addCategory(){categories.push({id:crypto.randomUUID(),name:'New Category',weight:0,mode:'points',assessments:[]});} function addAssessment(category:GradeCategory){category.assessments.push({id:crypto.randomUUID(),name:'New Assessment',earned:null,possible:null});} function removeAssessment(category:GradeCategory,id:string){category.assessments=category.assessments.filter(a=>a.id!==id);} function removeCategory(id:string){categories=categories.filter(c=>c.id!==id);} function addScaleRow(){gradingScale.push({id:crypto.randomUUID(),minimumPercent:0,label:'1.00'});} function removeScaleRow(id:string){gradingScale=gradingScale.filter(r=>r.id!==id);} function fmt(value:number|null){return value===null||!Number.isFinite(value)?'—':`${value.toFixed(2)}%`;}
  const equivalentLabel=$derived.by(()=>{if(result.performanceOnGradedWork===null||gradingScale.length===0)return null;return [...gradingScale].sort((a,b)=>b.minimumPercent-a.minimumPercent).find(r=>result.performanceOnGradedWork!>=r.minimumPercent)?.label??null;}); const input='min-h-11 w-full rounded-lg border border-line-strong bg-white px-3 text-ink outline-none focus:border-ims-blue-deep focus-visible:ring-3 focus-visible:ring-ims-blue/20';
</script>

<div class="grid gap-4"><section class="grid items-end gap-3 border border-line-strong bg-white p-4 sm:grid-cols-[1fr_auto]"><label class="grid gap-1.5 text-sm font-bold"><span>Gradebook name</span><input class={`${input} text-lg font-bold`} bind:value={name} placeholder="e.g. MATH 38…"/></label><span class="w-fit border border-green-200 bg-green-50 px-2 py-1 text-xs font-bold text-green-800">Stored on this device</span></section>
<section class="grid overflow-hidden border border-sky-900 bg-ims-blue-ink text-white sm:grid-cols-2 xl:grid-cols-4">{#each [['Performance on graded work',fmt(result.performanceOnGradedWork),'Pending assessments excluded.'],['Weighted points earned',`${result.earnedWeightedPoints.toFixed(2)} / 100`,'Contribution from entered scores.'],['Configured weights',`${result.enteredWeight.toFixed(0)}%`,Math.abs(result.enteredWeight-100)>.001?'Adjust categories to reach 100%.':'Weights are complete.'],...(equivalentLabel?[['Your custom equivalent',equivalentLabel,'Based on your scale below.']]:[])] as metric}<div class="grid min-h-28 content-end gap-1 border-b border-r border-white/15 p-4"><span class="text-xs text-sky-100">{metric[0]}</span><strong class={`font-mono text-3xl tracking-tight ${metric[0]==='Configured weights'&&Math.abs(result.enteredWeight-100)>.001?'text-yellow-200':''}`}>{metric[1]}</strong><small class="text-sky-100">{metric[2]}</small></div>{/each}</section>
<section class="grid gap-3"><header class="flex items-end justify-between border-b border-line pb-3"><div><p class="font-mono text-xs uppercase tracking-[.12em] text-ims-blue-ink">Grading structure</p><h2 class="text-2xl font-semibold">Categories & scores</h2></div><button class="min-h-11 border border-line-strong px-3 font-bold hover:bg-slate-50" type="button" onclick={addCategory}>+ Category</button></header><div class="grid gap-4">{#each categories as category}<section class="grid gap-4 border border-line-strong bg-white p-4"><div class="grid items-end gap-3 sm:grid-cols-[1fr_9rem_auto]"><label class="grid gap-1 text-sm font-bold"><span>Category</span><input class={input} bind:value={category.name} aria-label="Category name"/></label><label class="grid gap-1 text-sm font-bold"><span>Weight %</span><input class={input} type="number" min="0" max="100" step="0.1" bind:value={category.weight} aria-label={`${category.name} weight`}/></label><button class="min-h-11 border border-red-200 bg-red-50 px-3 font-bold text-danger" type="button" onclick={()=>removeCategory(category.id)} aria-label={`Remove ${category.name}`}>Remove</button></div>
<div class="grid items-end gap-3 sm:grid-cols-[1fr_auto]"><label class="grid gap-1 text-sm font-bold"><span>Calculation method</span><select class={input} bind:value={category.mode}><option value="points">Total points within category</option><option value="equal-average">Equal average per assessment</option></select></label><div class="grid min-w-28"><span class="text-xs text-muted">Current</span><strong class="font-mono text-2xl text-ims-blue-ink">{fmt(result.categories.find(i=>i.id===category.id)?.percent??null)}</strong></div></div>
<div class="grid gap-2" role="group" aria-label={`${category.name} assessments`}>{#if category.assessments.length===0}<p class="border border-dashed border-line p-3 text-sm text-muted">No assessments yet. Add one when you have a score or want to plan.</p>{/if}{#each category.assessments as assessment}<div class="grid items-end gap-2 border-l-4 border-ims-blue-deep bg-slate-50 p-3 sm:grid-cols-[1fr_6rem_6rem_2.75rem]"><label class="grid gap-1 text-xs font-bold"><span>Assessment</span><input class={input} bind:value={assessment.name}/></label><label class="grid gap-1 text-xs font-bold"><span>Score</span><input class={input} type="number" min="0" step="0.01" bind:value={assessment.earned} placeholder="—" inputmode="decimal"/></label><label class="grid gap-1 text-xs font-bold"><span>Total</span><input class={input} type="number" min="0" step="0.01" bind:value={assessment.possible} placeholder="—" inputmode="decimal"/></label><button class="grid size-11 place-items-center border border-red-200 bg-white text-xl text-danger" type="button" onclick={()=>removeAssessment(category,assessment.id)} aria-label={`Remove ${assessment.name}`}>×</button></div>{/each}</div><button class="min-h-11 border border-dashed border-line-strong font-bold text-ims-blue-ink" type="button" onclick={()=>addAssessment(category)}>+ Add Assessment</button></section>{/each}</div></section>
<section class="grid gap-4 lg:grid-cols-2"><article class="grid content-start gap-4 border-t-4 border-ims-yellow bg-white p-5"><p class="font-mono text-xs uppercase tracking-[.12em] text-ims-blue-ink">Target tool</p><h2 class="text-2xl font-semibold">What do I need on the remaining weight?</h2><label class="grid max-w-40 gap-1 text-sm font-bold"><span>Target final %</span><input class={input} type="number" min="0" max="100" step="0.1" bind:value={target}/></label>{#if required!==null}{#if required>100}<p class="border-l-4 border-danger bg-red-50 p-3 text-red-900">You need <strong>{required.toFixed(2)}%</strong> across the remaining {remainingWeight.toFixed(1)}% weight—above 100%.</p>{:else if required<=0}<p class="border-l-4 border-ims-green bg-green-50 p-3 text-green-900">Entered weighted points already cover this target under the current structure.</p>{:else}<p class="border-l-4 border-ims-yellow bg-yellow-50 p-3 text-amber-950">Required average across the remaining {remainingWeight.toFixed(1)}%: <strong>{required.toFixed(2)}%</strong>.</p>{/if}{:else}<p class="text-muted">No remaining weight is available for this calculation.</p>{/if}</article>
<article class="grid content-start gap-4 border-t-4 border-ims-blue-deep bg-white p-5"><p class="font-mono text-xs uppercase tracking-[.12em] text-ims-blue-ink">What-if mode</p><h2 class="text-2xl font-semibold">Test one pending score.</h2>{#if pendingAssessments.length}<label class="grid gap-1 text-sm font-bold"><span>Pending assessment</span><select class={input} bind:value={whatIfAssessmentId}><option value="">Choose an assessment</option>{#each pendingAssessments as item}<option value={item.assessmentId}>{item.label}</option>{/each}</select></label><div class="grid grid-cols-[1fr_auto_1fr] items-end gap-2"><label class="grid gap-1 text-sm font-bold"><span>Score</span><input class={input} type="number" min="0" step=".01" bind:value={whatIfEarned} inputmode="decimal"/></label><span class="grid min-h-11 place-items-center text-muted">/</span><label class="grid gap-1 text-sm font-bold"><span>Out of</span><input class={input} type="number" min="0" step=".01" bind:value={whatIfPossible} inputmode="decimal"/></label></div><div class="border border-line bg-slate-50 p-3"><span class="block text-xs text-muted">Projected performance</span><strong class="font-mono text-2xl text-ims-blue-ink">{fmt(projectedResult?.performanceOnGradedWork??null)}</strong><small class="block text-muted">Actual scores are not overwritten.</small></div>{:else}<p class="text-muted">Add a pending assessment to use what-if mode.</p>{/if}</article></section>
<section class="grid gap-4 border border-line-strong bg-white p-5"><header class="flex flex-col gap-3 border-b border-line pb-3 sm:flex-row sm:items-start sm:justify-between"><div><p class="font-mono text-xs uppercase tracking-[.12em] text-ims-blue-ink">Optional</p><h2 class="text-2xl font-semibold">Custom grading scale</h2><p class="max-w-prose text-muted">Enter only the conversion table published for your course.</p></div><button class="min-h-11 border border-line-strong px-3 font-bold" type="button" onclick={addScaleRow}>+ Scale Row</button></header>{#if gradingScale.length===0}<p class="text-muted">No conversion added. Percentage calculations still work.</p>{:else}<div class="grid gap-2">{#each gradingScale as row}<div class="grid items-end gap-2 sm:grid-cols-[1fr_1fr_2.75rem]"><label class="grid gap-1 text-sm font-bold"><span>Minimum %</span><input class={input} type="number" min="0" max="100" step=".01" bind:value={row.minimumPercent}/></label><label class="grid gap-1 text-sm font-bold"><span>Equivalent label</span><input class={input} bind:value={row.label} placeholder="e.g. 1.25…"/></label><button class="grid size-11 place-items-center border border-red-200 text-xl text-danger" type="button" onclick={()=>removeScaleRow(row.id)} aria-label="Remove grading scale row">×</button></div>{/each}</div>{/if}</section></div>
